type Event = {
  turnId: string;
  kind: string;
  [key: string]: unknown;
};

type Tool = {
  id: string;
  title: string;
  status: "pending" | "running" | "completed" | "failed";
  output: string;
};

type Turn = {
  text: string;
  tools: Tool[];
  stopReason: string | null;
};

type ToolEvent = Event & {
  id: string;
  title?: string;
  status?: Tool["status"];
  output?: string | null;
  outputMode?: "append" | "replace";
};

export function assembleTurn(turnId: string, events: Event[]): Turn {
  let text = "";
  let stopReason: string | null = null;
  const tools: Tool[] = [];
  const toolsById = new Map<string, Tool>();

  for (const event of events) {
    if (event.turnId !== turnId) continue;

    if (event.kind === "done") {
      stopReason = event.stopReason as string;
      break;
    }

    if (event.kind === "message") {
      const message = event.text as string;
      text = event.mode === "replace" ? message : text + message;
      continue;
    }

    if (event.kind !== "tool") continue;

    const update = event as ToolEvent;
    let tool = toolsById.get(update.id);

    if (tool === undefined) {
      tool = {
        id: update.id,
        title: "",
        status: "pending",
        output: "",
      };
      toolsById.set(update.id, tool);
      tools.push(tool);
    }

    if (update.title !== undefined) tool.title = update.title;
    if (update.status !== undefined) tool.status = update.status;

    if (update.output === null) {
      tool.output = "";
    } else if (update.output !== undefined) {
      tool.output =
        update.outputMode === "replace"
          ? update.output
          : tool.output + update.output;
    }
  }

  return { text, tools, stopReason };
}
